  h.querySelectorAll('.depth-nodes button').forEach(b=>{const pt=points.get(b.dataset.depthNode);b.style.left=pt.x/840*width+'px';b.style.top=pt.y/540*height+'px';b.style.transform=`translate(-50%,-50%) scale(${Math.max(.65,Math.min(1.15,pt.scale))})`;b.style.zIndex=Math.round(pt.depth+400);b.dataset.selected=String(scene.selected===b.dataset.depthNode)});
  h.querySelector('.depth-lines').innerHTML=scene.draw.links.map(l=>{const a=points.get(l.from),b=points.get(l.to),active=l.from===scene.selected||l.to===scene.selected;return `<path d="M${a.x} ${a.y} L${b.x} ${b.y}" class="${l.type==='challenges'?'challenge':''} ${active?'selected':''}"/>`}).join('');
