  const context=n.kind==='source'?`${r.authors||'Authors not recorded'} · ${r.year||'Year not recorded'}\n${r.abstract||'Abstract not recorded'}`:n.kind==='evidence'?`${r.quote||'Exact passage not recorded'}\nLocation: ${r.locator||'Not recorded'}\nMethod: ${r.method||'Not recorded'}\nLimitations: ${r.limitations||'Not recorded'}`:n.kind==='theme'?`${r.definition||'Definition not recorded'}\nInterpretation: ${r.conclusion||'Not recorded'}\nOpen questions / boundaries: ${r.gaps||'Not recorded'}`:`Status: ${r.status}\n${r.text}`;
  scene.host.querySelector('.depth-inspector').innerHTML=`<span class="depth-kind-label">${esc(n.tag)} · ${esc(n.kind)}</span><h3>${esc(n.label)}</h3><p class="depth-context">${esc(context)}</p>${link(target,'Open '+n.kind+' in its room',r.id)}<h4>${connections.length} recorded relationships</h4>${connections.map(l=>{const other=related(l.from===key?l.to:l.from);return `<div class="depth-relationship"><strong>${esc(l.type)} · ${l.from===key?'to':'from'} ${esc(other.tag)}</strong><button type="button" class="text-button" data-depth-node="${esc(other.key)}">${esc(other.label)}</button><p>${esc(l.detail)}</p></div>`}).join('')||'<p>This record has no recorded connections. That does not prove a gap in the wider literature.</p>'}`;
